#include <cctype>
#include <iostream>
#include <string>

bool isPalindrome(const std::string& s) {
    int left = 0;
    int right = static_cast<int>(s.size()) - 1;
    while (left < right) {
        unsigned char a = s[left];
        unsigned char b = s[right];
        if (!std::isalnum(a)) {
            left++;
        } else if (!std::isalnum(b)) {
            right--;
        } else if (std::tolower(a) != std::tolower(b)) {
            return false;
        } else {
            left++;
            right--;
        }
    }
    return true;
}

int main() {
    std::string s;
    std::getline(std::cin, s);
    std::cout << (isPalindrome(s) ? "true" : "false") << "\n";
    return 0;
}

