package main

import (
	"bufio"
	"fmt"
	"os"
	"unicode"
)

func isLetterOrDigit(r rune) bool {
	return unicode.IsLetter(r) || unicode.IsDigit(r)
}

func isPalindrome(s string) bool {
	runes := []rune(s)
	left, right := 0, len(runes)-1
	for left < right {
		a, b := runes[left], runes[right]
		if !isLetterOrDigit(a) {
			left++
		} else if !isLetterOrDigit(b) {
			right--
		} else if unicode.ToLower(a) != unicode.ToLower(b) {
			return false
		} else {
			left++
			right--
		}
	}
	return true
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Scan()
	fmt.Println(isPalindrome(scanner.Text()))
}

